/**
 * @method
 * @name scwin.disclosure_type
 * @author Inswave
 * @date 2026. 09. 29
 * @param code
 * @returns
 * @hidden N
*/
scwin.disclosure_type = function (code) {
    /* sdd-asis-lifecycle:begin disclosure_type — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const layer = "layer" + code;
    const imgId = "dTypeImg" + code;
    ($c.util.getComponent("iconBoxLayer") && $c.util.getComponent("iconBoxLayer").hide ? $c.util.getComponent("iconBoxLayer").hide() : console.warn('[sdd] hide 대상 미해결: ' + "iconBoxLayer"));
    const myImg = parseInt(code, 10);
    if ($c.util.getComponent(imgId).value === "on") {
        $c.util.getComponent(imgId).src = "../images/common/puplic" + myImg + "_off.gif";
        $c.util.getComponent(imgId).setValue("off");
    } else {
        $c.util.getComponent(imgId).src = "../images/common/puplic" + myImg + "_on.gif";
        $c.util.getComponent(imgId).setValue("on");
    }
    if ($c.util.getComponent(imgId).value === "on") {
        ($c.util.getComponent(layer) && $c.util.getComponent(layer).show ? $c.util.getComponent(layer).show() : console.warn('[sdd] show 대상 미해결: ' + layer));
    } else {
        if ($c.util.getComponent(imgId).value === "off") {
            ($c.util.getComponent(layer) && $c.util.getComponent(layer).hide ? $c.util.getComponent(layer).hide() : console.warn('[sdd] hide 대상 미해결: ' + layer));
        }
    }
    ($c.util.getComponent("iconBoxLayer") && $c.util.getComponent("iconBoxLayer").show ? $c.util.getComponent("iconBoxLayer").show() : console.warn('[sdd] show 대상 미해결: ' + "iconBoxLayer"));
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.disclosure_window_check
 * @author Inswave
 * @date 2026. 09. 29
 * @param code
 * @returns
 * @hidden N
*/
scwin.disclosure_window_check = function (code) {
    /* sdd-asis-lifecycle:begin disclosure_window_check — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const dMom = eval("document.frm.publicAll" + code);
    const dName = eval("document.frm.disclosureTypeArr" + code);
    if (dMom.checked === true) {
        if (dName.length == null) {
            dName.checked = true;
        } else {
            for (let i = 0; i < dName.length; i++) {
                dName[i].checked = true;
            }
        }
    } else {
        if (dName.length == null) {
            dName.checked = false;
        } else {
            for (let j = 0; j < dName.length; j++) {
                dName[j].checked = false;
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


