/**
 * @method
 * @name scwin.order_by
 * @author Inswave
 * @date 2026. 09. 29
 * @param val startVal
 * @returns
 * @hidden N
*/
scwin.order_by = async function (val, startVal) {
    /* sdd-asis-lifecycle:begin order_by — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('dma_changeBusinessReq').set('orderIndex', val);
    $c.util.getComponent("orderType1").className = "";
    $c.util.getComponent("orderType2").className = "";
    $c.util.getComponent("orderType3").className = "";
    if (val === "") {
        $c.util.getComponent("orderType1").className = "on";
        (document.frm || { elements: [] }).orderMode.value = "1";
    }
    if (val === "1" && $c.util.getComponent("orderType1").className === "") {
        $c.util.getComponent("orderType1").className = "on";
        if (startVal === "ok") {
            await scwin.fncSearch();
        }
    }
    if (val === "2" && $c.util.getComponent("orderType2").className === "") {
        $c.util.getComponent("orderType2").className = "on";
        if (startVal === "ok") {
            await scwin.fncSearch();
        }
    }
    if (val === "3" && $c.util.getComponent("orderType3").className === "") {
        $c.util.getComponent("orderType3").className = "on";
        if (startVal === "ok") {
            await scwin.fncSearch();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.disclosureSetting
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.disclosureSetting = function () {
    /* sdd-asis-lifecycle:begin disclosureSetting — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let get_name = "";
    let set_name = "";
    let check_setting = "";
    for (let i = 1; i < 12; i++) {
        check_setting = "";
        if (i < 10) {
            get_name = eval("document.frm.disclosureTypeArr0" + i);
            set_name = eval("document.frm.pDisclosureType0" + i);
        } else {
            get_name = eval("document.frm.disclosureTypeArr" + i);
            set_name = eval("document.frm.pDisclosureType" + i);
        }
        if (get_name.length == null) {
            if (get_name.checked === true) {
                check_setting = check_setting + get_name.value + "|";
            }
        } else {
            for (let j = 0; j < get_name.length; j++) {
                if (get_name[j].checked === true) {
                    check_setting = check_setting + get_name[j].value + "|";
                }
            }
        }
        set_name.value = check_setting;
    }
    /* sdd-asis-lifecycle:end */
};


