/**
 * @method
 * @name scwin.fncSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fncSearch = async function () {
    /* sdd-asis-lifecycle:begin fncSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.disclosure_window_all_close();
    scwin.disclosureSetting();
    if (!$c.date.isDate($c.util.getComponent('cal_fromData').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toData').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_fromData').getValue(), $c.util.getComponent('cal_toData').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    $c.util.getComponent('dma_changeBusinessReq').set('method', "searchDisclosureByIndustrySub");
    $c.util.getComponent('dma_changeBusinessReq').set('forward', "searchdisclosurebyindustry_sub");
    $c.util.getComponent("dma_changeBusinessReq").set("currentPageSize", document.iframe.document.iFrm.currentPageSize.value);
    $c.util.getComponent("dma_changeBusinessReq").set("pageIndex", document.iframe.document.iFrm.pageIndex.value);
    (document.frm || { elements: [] }).target = "iframe";
    await scwin.tx_fncSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await scwin.changeBusiness();
    ($c.util.getComponent("iconBoxLayer") && $c.util.getComponent("iconBoxLayer").hide ? $c.util.getComponent("iconBoxLayer").hide() : console.warn('[sdd] hide 대상 미해결: ' + "iconBoxLayer"));
    scwin.disclosure_window_all_close();
    scwin.disclosureSetting();
    ($c.util.getComponent("iconBoxLayer") && $c.util.getComponent("iconBoxLayer").show ? $c.util.getComponent("iconBoxLayer").show() : console.warn('[sdd] show 대상 미해결: ' + "iconBoxLayer"));
    if (!$c.date.isDate($c.util.getComponent('cal_fromData').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toData').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (!($c.date.diffDate($c.util.getComponent('cal_fromData').getValue(), $c.util.getComponent('cal_toData').getValue()) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
        return;
    }
    for (let i = 0; i < scwin.discloureArr.length; i++) {
        $c.util.getComponent("disclosureType" + scwin.discloureArr[i]).setValue($c.util.getComponent("pDisclosureType" + scwin.discloureArr[i]).getValue());
    }
    if ($c.util.getComponent("ipt_bfrDsclsType").checked === true) {
        scwin.clearDType();
    }
    $c.util.getComponent("dma_changeBusinessReq").set("isurCd", "");
    $c.util.getComponent('dma_changeBusinessReq').set('method', "searchDisclosureByIndustrySub");
    $c.util.getComponent('dma_changeBusinessReq').set('forward', "searchdisclosurebyindustry_sub");
    $c.util.getComponent("dma_changeBusinessReq").set("currentPageSize", document.iframe.document.iFrm.currentPageSize.value);
    $c.util.getComponent("dma_changeBusinessReq").set("pageIndex", "1");
    (document.frm || { elements: [] }).target = "iframe";
    await scwin.tx_fn_Search();
    /* sdd-asis-lifecycle:end */
};


