/**
 * @method
 * @name scwin.clearDType
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.clearDType = function () {
    /* sdd-asis-lifecycle:begin clearDType — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const all_input = document.getElementsByTagName("input");
    for (var i = 0; i < all_input.length; i++) {
        if (all_input[i].type === "checkbox" && all_input[i].checked === true) {
            if (all_input[i].name !== "bfrDsclsType") {
                all_input[i].checked = false;
            }
        }
    }
    for (var i = 0; i < scwin.discloureArr.length; i++) {
        $c.util.getComponent("pDisclosureType" + scwin.discloureArr[i]).setValue("");
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnBfrDsclsType
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnBfrDsclsType = async function () {
    /* sdd-asis-lifecycle:begin fnBfrDsclsType — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if ($c.util.getComponent("ipt_bfrDsclsType").checked === true) {
        if (await $c.win.confirm("선택한 공시유형이 모두 초기화됩니다.\n진행하시겠습니까?")) {
            const all_input = document.getElementsByTagName("input");
            for (let i = 0; i < all_input.length; i++) {
                if (all_input[i].type === "checkbox" && all_input[i].checked === true) {
                    if (all_input[i].name !== "bfrDsclsType") {
                        all_input[i].checked = false;
                    }
                }
            }
        } else {
            $c.util.getComponent("ipt_bfrDsclsType").checked = false;
        }
    }
    /* sdd-asis-lifecycle:end */
};


